import sqlite3
import json
from pymilvus import connections, Collection
import numpy as np
from sentence_transformers import SentenceTransformer

# Initialize sentence transformer for embedding generation
model = SentenceTransformer('all-MiniLM-L6-v2')

# Database paths
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}


def connect_sqlite(db_name):
    conn = sqlite3.connect(sqlite_paths[db_name])
    conn.row_factory = sqlite3.Row
    return conn


def parse_attributes(attr_str):
    """Parse the JSON-like attributes string into a dictionary."""
    if not attr_str:
        return {}
    try:
        # Replace single quotes with double quotes for valid JSON
        attr_str = attr_str.replace("'", '"')
        return json.loads(attr_str)
    except Exception as e:
        # Fallback: simple parsing
        attrs = {}
        for pair in attr_str.strip('{}').split(','):
            if ':' in pair:
                k, v = pair.split(':', 1)
                attrs[k.strip().strip('"')] = v.strip().strip('"')
        return attrs


def has_wifi_and_outlets(attributes_dict):
    """Check if business has WiFi and power outlets."""
    wifi = attributes_dict.get('WiFi', 'no').lower() in ['free', 'paid', 'yes']
    # Power outlets might be mentioned in various ways
    outlets = any(kw in str(attributes_dict).lower() for kw in ['power', 'outlet', 'socket'])
    return wifi and outlets


def main():
    # Step 1: Get coffee shops in Philadelphia
    conn_business = connect_sqlite('business')
    cursor = conn_business.cursor()
    cursor.execute("""
        SELECT business_id, name, address, attributes 
        FROM business 
        WHERE city = ? AND categories LIKE ?
    """, ('Philadelphia', '%Coffee%'))

    philly_coffee_shops = []
    for row in cursor.fetchall():
        attrs = parse_attributes(row['attributes'])
        philly_coffee_shops.append({
            'business_id': row['business_id'],
            'name': row['name'],
            'address': row['address'],
            'attributes': attrs
        })

    conn_business.close()

    # Step 2: Filter by WiFi and power outlets
    filtered_coffee_shops = [
        shop for shop in philly_coffee_shops 
        if has_wifi_and_outlets(shop['attributes'])
    ]

    filtered_ids = {shop['business_id'] for shop in filtered_coffee_shops}

    if not filtered_ids:
        print("No coffee shops found with WiFi and power outlets in Philadelphia.")
        return

    # Step 3: Semantic search in Milvus
    connections.connect(host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])

    query_text = "quiet place good for studying or working"
    query_embedding = model.encode([query_text])[0].tolist()

    relevant_business_ids = set()

    # Search in reviews collection
    try:
        reviews_collection = Collection(milvus_config['milvus_collections']['reviews'])
        reviews_results = reviews_collection.search(
            data=[query_embedding],
            anns_field="vector",
            param={"metric_type": "L2", "params": {"nprobe": 10}},
            limit=50,
            output_fields=["business_id"]
        )
        for hits in reviews_results:
            for hit in hits:
                relevant_business_ids.add(hit.entity.get('business_id'))
    except Exception as e:
        print(f"Warning: Could not search reviews collection: {e}")

    # Search in tips collection
    try:
        tips_collection = Collection(milvus_config['milvus_collections']['tips'])
        tips_results = tips_collection.search(
            data=[query_embedding],
            anns_field="vector",
            param={"metric_type": "L2", "params": {"nprobe": 10}},
            limit=50,
            output_fields=["business_id"]
        )
        for hits in tips_results:
            for hit in hits:
                relevant_business_ids.add(hit.entity.get('business_id'))
    except Exception as e:
        print(f"Warning: Could not search tips collection: {e}")

    # Step 4: Intersection
    final_ids = filtered_ids & relevant_business_ids
    final_coffee_shops = [shop for shop in filtered_coffee_shops if shop['business_id'] in final_ids]

    # Output results
    if final_coffee_shops:
        print(f"Found {len(final_coffee_shops)} coffee shops in Philadelphia suitable for studying/working:")
        for shop in final_coffee_shops:
            print(f"- {shop['name']} at {shop['address']}")
    else:
        print("No coffee shops found that meet all criteria.")
        # Optionally return filtered shops without semantic match
        if filtered_coffee_shops:
            print("\nHere are coffee shops with WiFi and outlets (may not be quiet):")
            for shop in filtered_coffee_shops[:5]:
                print(f"- {shop['name']} at {shop['address']}")

if __name__ == "__main__":
    main()
